mapper.select:
SELECT l.id, e.warehouse_id, 0 AS region_id, l.sku_code, CASE WHEN l.reserved_delta != 0 AND l.quantity_delta = 0 THEN 'RESERVED' WHEN l.quality = 'DEFECTIVE' THEN 'DAMAGED' ELSE 'AVAILABLE' END AS bucket, CASE WHEN l.quantity_delta < 0 OR (l.quantity_delta = 0 AND l.reserved_delta < 0) THEN 'OUT' ELSE 'IN' END AS direction, ABS(CASE WHEN l.quantity_delta != 0 THEN l.quantity_delta ELSE l.reserved_delta END) AS quantity, l.before_quantity, l.after_quantity, e.id AS posting_id, e.event_no AS posting_no, l.id AS posting_item_id, e.event_type AS posting_type, e.source_type, e.source_id, e.source_no, e.reason AS remark, e.operator_id AS create_by, e.occurred_at AS create_time, l.location_id, loc.location_code, l.counterpart_location_id, target.location_code AS counterpart_location_code, l.quality, l.quantity_delta, l.reserved_delta, l.before_reserved, l.after_reserved FROM wms_inventory_event_line l JOIN wms_inventory_event e ON e.id = l.event_id LEFT JOIN wms_location loc ON loc.id = l.location_id AND loc.deleted = 0 LEFT JOIN wms_location target ON target.id = l.counterpart_location_id AND target.deleted = 0 WHERE 1 = 1
AND e.warehouse_id = #{qo.warehouseId}
AND e.warehouse_id IN #{warehouseId}
AND 1 = 0 AND l.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%') AND e.event_type = #{qo.postingType}
AND e.event_type IN #{type}
AND e.source_no LIKE CONCAT('%', #{qo.sourceNo}, '%') AND e.event_no LIKE CONCAT('%', #{qo.postingNo}, '%') AND e.occurred_at >= #{qo.startTime} AND e.occurred_at <= #{qo.endTime} AND (l.quantity_delta > 0 OR (l.quantity_delta = 0 AND l.reserved_delta > 0)) AND (l.quantity_delta < 0 OR (l.quantity_delta = 0 AND l.reserved_delta < 0)) ORDER BY e.occurred_at DESC, l.id DESC

SELECT DISTINCT e.event_type FROM wms_inventory_event e
JOIN wms_inventory_event_line l ON l.event_id = e.id
WHERE 1 = 1

AND e.warehouse_id = #{warehouseId}
AND l.sku_code = #{skuCode}
ORDER BY e.event_type

SELECT e.id, e.event_no AS posting_no, e.warehouse_id, 0 AS region_id,
       e.event_type AS posting_type, e.source_type, e.source_id, e.source_no,
       e.occurred_at AS biz_time, e.occurred_at AS post_time, e.reason AS remark,
       e.operator_id AS create_by, e.create_time,
       COUNT(DISTINCT l.sku_code) AS sku_count,
       SUM(ABS(CASE WHEN l.quantity_delta != 0 THEN l.quantity_delta ELSE l.reserved_delta END)) AS total_quantity
FROM wms_inventory_event e JOIN wms_inventory_event_line l ON l.event_id = e.id
WHERE 1 = 1

AND e.event_no LIKE CONCAT('%', #{qo.postingNo}, '%')
AND e.warehouse_id = #{qo.warehouseId}
AND e.event_type = #{qo.postingType}
AND e.source_type = #{qo.sourceType}
AND e.source_no LIKE CONCAT('%', #{qo.sourceNo}, '%')
AND e.occurred_at >= #{qo.postTimeStart}
AND e.occurred_at <= #{qo.postTimeEnd}
GROUP BY e.id ORDER BY e.occurred_at DESC, e.id DESC


WHERE e.id = #{eventId}

AND l.sku_code LIKE CONCAT('%', #{skuCode}, '%')
ORDER BY l.line_no


WHERE e.id = #{qo.postingId}

    AND e.erp_tenant_id IN
    #{ownerId}

AND l.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%')
ORDER BY l.line_no
